-- Responsabilidades > Relaciones institucionales > Contactos: guarda los correos de la lista de clubes
-- (Primera RFEF y Segunda RFEF) sobre los contactos ya existentes.
--   · Solo rellena contactos cuyo correo está VACÍO: nunca pisa un correo que ya hayas puesto tú.
--   · Cada contacto se localiza por su id (seed-...) o por el nombre de la entidad.
--   · Las notas solo se actualizan si siguen siendo las originales del script contactos_clubes.sql.
--   · Los clubes «sin email público» no se tocan. Si una celda traía dos correos, el primero va al campo
--     Correo y el segundo se anota en Notas (el campo solo admite un correo válido).
--   · Es seguro ejecutarlo varias veces.
-- Requisito: haber ejecutado antes contactos_clubes.sql (o tener ya los contactos en el panel).
-- Ejecutar: npx wrangler d1 execute <BASE_DE_DATOS> --remote --file=contactos_clubes_correos.sql

UPDATE settings
SET value = json_set(
      value,
      '$.relaciones.contactos',
      json((
        SELECT json_group_array(json(j)) FROM (
          SELECT COALESCE(
                   (SELECT json_set(
                             e.value,
                             '$.email', json_extract(p.value, '$.email'),
                             '$.area', json_extract(p.value, '$.area'),
                             '$.notas', CASE WHEN COALESCE(json_extract(e.value, '$.notas'), '') = json_extract(p.value, '$.old')
                                             THEN json_extract(p.value, '$.new')
                                             ELSE json_extract(e.value, '$.notas') END)
